using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class ApprovalReassignmentTests
{
 class User(int userId=1,int empId=1,bool admin=true):ICurrentUser{public string Email=>"actor"+userId+"@example.local";public int? EmployeeId=>empId;public int UserId=>userId;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>admin;public bool Can(string p)=>admin;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static ApprovalService S(AppDbContext d,User? u=null){u??=new();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,new AccessScope(d,u),u,a,new NotificationService(d,u,c),c,new WorkflowService(d,u,a),new DelegationService(d,u,a,c));}
 static async Task<(OvertimeRequest R,AppUser U)> Setup(AppDbContext d){var r=new OvertimeRequest{EmployeeId=6,Date=new(2026,11,23),Hours=2,Route="HRManager,FinanceManager"};var u=new AppUser{EmployeeId=5,Email="assigned@example.local",PasswordHash="disabled-test",RoleList=Roles.Employee};d.AddRange(r,u);await d.SaveAsync();return(r,u);}
 [Fact]public async Task ReassignedUserSeesAndActsOnlyForCurrentStage(){await using var d=await Db();var(r,u)=await Setup(d);await S(d).ReassignAsync("Overtime",r.Id,0,u.Id,"Manager unavailable");Assert.Equal("HRManager,FinanceManager",r.Route);Assert.Equal(RequestStatus.Pending,r.Status);var actor=S(d,new(u.Id,5,false));var rows=await actor.ListAsync("Overtime",RequestStatus.Pending,true);Assert.Contains(rows,x=>x.Id==r.Id&&x.AssignedTo==u.Email);await actor.ApproveAsync("Overtime",r.Id,"Reviewed");Assert.Equal(1,r.StageIndex);Assert.Equal(RequestStatus.Pending,r.Status);await Assert.ThrowsAsync<DomainException>(()=>actor.ApproveAsync("Overtime",r.Id,"Again"));Assert.Single(await d.Set<ApprovalAssignment>().ToListAsync());Assert.True(await d.Set<Notification>().AnyAsync(x=>x.UserId==u.Id&&x.TitleKey=="notif.reassigned"));}
 [Fact]public async Task UnauthorizedSelfInactiveAndStaleReassignmentAreRejected(){await using var d=await Db();var(r,u)=await Setup(d);await Assert.ThrowsAsync<DomainException>(()=>S(d,new(u.Id,5,false)).ReassignAsync("Overtime",r.Id,0,u.Id,"No authority"));var own=await d.Set<AppUser>().FirstAsync(x=>x.EmployeeId==6);await Assert.ThrowsAsync<DomainException>(()=>S(d).ReassignAsync("Overtime",r.Id,0,own.Id,"Self"));await Assert.ThrowsAsync<DomainException>(()=>S(d).ReassignAsync("Overtime",r.Id,1,u.Id,"Stale"));await Assert.ThrowsAsync<DomainException>(()=>S(d).ReassignAsync("Overtime",r.Id,0,u.Id," "));u=await d.Set<AppUser>().FindAsync(u.Id)??u;u.IsActive=false;await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d).ReassignAsync("Overtime",r.Id,0,u.Id,"Inactive"));Assert.Empty(await d.Set<ApprovalAssignment>().ToListAsync());}
 [Fact]public async Task NewReassignmentSupersedesPreviousAndEvidenceIsImmutable(){await using var d=await Db();var(r,u)=await Setup(d);await S(d).ReassignAsync("Overtime",r.Id,0,u.Id,"First");var next=new AppUser{EmployeeId=4,Email="next@example.local",PasswordHash="disabled-test"};d.Add(next);await d.SaveAsync();await S(d).ReassignAsync("Overtime",r.Id,0,next.Id,"Replacement");await Assert.ThrowsAsync<DomainException>(()=>S(d,new(u.Id,5,false)).ApproveAsync("Overtime",r.Id,"Stale assignee"));await S(d,new(next.Id,4,false)).ApproveAsync("Overtime",r.Id,"Checked");Assert.Equal(2,await d.Set<ApprovalAssignment>().CountAsync());var evidence=await d.Set<ApprovalAssignment>().FirstAsync();evidence.Reason="tamper";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());d.ChangeTracker.Clear();var action=await d.Set<ApprovalAction>().FirstAsync();d.Remove(action);await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
}
